('alict_01277', 7, 'Database Management Systems', 'What SQL command would use to delete all rows where the salary column is less than 20000?', '["DELETE * FROM employees WHERE salary", "DELETE age FROM employees WHERE salary", "DROP employees WHERE salary", "DELETE FROM employees WHERE salary", "REMOVE FROM employees WHERE salary"]'::jsonb, 4, 'In the command that used to delete rows from tables are DELETE FROM WHERE The WHERE clause is used to filter records based on a condition. Only the records that satisfy the condition will be affected by the DELETE operation', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1277, 'A/L Past Paper Series'),
