('alict_01279', 7, 'Database Management Systems', 'Which of the following SQL operations is not always guaranteed to be ACID-compliant in a distributed database system?', '["SELECT", "COMMIT", "INSERT", "JOIN", "UPDATE"]'::jsonb, 4, 'JOIN operations are not always ACID-compliant in distributed databases due to consistency challenges across multiple nodes. nyq Option 01 SELECT queries do not modify so they remain ACID-compliant as they do not impact transaction integrity', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1279, 'A/L Past Paper Series'),
('alict_01280', 7, 'Database Management Systems', 'Which SQL keyword is used to retrieve only unique records from a table?', '["DISTINCT", "GROUP BY", "UNIQUE", "FILTER", "ORDER BY"]'::jsonb, 1, 'Option 1: Correct. The DISTINCT keyword removes duplicate values from the result set. Option 2: Incorrect. GROUP BY groups data but does not necessarily remove duplicates. Option 3: Incorrect. UNIQUE is a constraint on a not a keyword for queries. Option 4: Incorrect', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1280, 'A/L Past Paper Series'),
('alict_01281', 7, 'Database Management Systems', 'Which SQL function is used to remove duplicate values from a column?', '["COUNT()", "DISTINCT", "FILTER()", "UNIQUE()", "REMOVE_DUPLICATES()"]'::jsonb, 2, 'Option 1: COUNT() is used to count the number of rows in a table. Option 2: DISTINCT removes duplicate values from the result set. Option 3: FILTER() is used in some SQL databases to apply a condition inside aggregate functions', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1281, 'A/L Past Paper Series'),
