('alict_01307', 7, 'Database Management Systems', 'What is the main purpose of the ALTER TABLE command in SQL?', '["To retrieve data from a table", "To change the structure of an existing table", "To delete a table", "To insert new rows into a table", "To roll back changes in a table"]'::jsonb, 2, 'Option 1: Retrieving data is done using SELECT command. SELECT Option 2: The main purpose of the ALTER TABLE command is to modify an existing table. It allows or deleting or indexes. ALTER TABLE Option 3: Deleting a table is done using DROP TABLE command. j', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1307, 'A/L Past Paper Series'),
('alict_01308', 7, 'Database Management Systems', 'What will happen if you try to insert a NULL value into a column defined as NOT NULL?', '["The NULL value will be stored in the column", "The database will replace NULL with a default value", "The insertion will fail with an error", "The database will delete the row instead", "The NULL value will be converted to an empty string. NULL w.h ysia string tlla"]'::jsonb, 3, 'Option 1: NULL cannot be stored in a NOT NULL column. NULL w.h NOT NULL Option 2: The database does not automatically assign default values unless specified. Option 3: Correct. If a column is defined with NOT it must always contain a value', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1308, 'A/L Past Paper Series'),
