('alict_01312', 7, 'Database Management Systems', 'Which of the following SQL queries retrieves the names of customers who have not placed any orders?', '["SELECT name FROM Customers WHERE customer_id NOT IN (SELECT customer_id FROM", "SELECT name FROM Customers JOIN Orders ON Customers.customer_id =", "SELECT name FROM Customers WHERE EXISTS (SELECT * FROM Orders WHERE customer_id =", "SELECT name FROM Orders WHERE customer_id IS", "SELECT name FROM Customers WHERE customer_id IN (SELECT customer_id FROM"]'::jsonb, 1, 'Option 1: This query selects names from the Customers table where the customer_id does not appear in the Orders table. This is the correct approach for identifying customers who have not placed any orders', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1312, 'A/L Past Paper Series'),
('alict_01313', 7, 'Database Management Systems', 'What does this SQL query do?', '["Selects names starting with", "Selects names with as second letter", "Selects names ending with", "Selects names containing anywhere", "Selects names with as the first letter"]'::jsonb, 2, 'This SQL query uses the LIKE operator to filter rows based on a pattern in the "Name" column. SQL The pattern ''_a%'' can be broken down into three ''_a%'' fldgia The underscore _ means exactly one so the first letter of the name can be any single character', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1313, 'A/L Past Paper Series'),
('alict_01314', 7, 'Database Management Systems', 'What does the keyword in SQL do?', '["To search for specific patterns in a column", "To create different outputs based on conditions", "To update a view", "To rename a column or table", "To sort the result set in ascending order"]'::jsonb, 4, 'Option 1: This functionality is achieved using the LIKE keyword in SQL. The LIKE keyword is used in a WHERE clause to search for a specified pattern in a column. For it can be used to find all entries in a column that start with a specific letter or contain a certain substring', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1314, 'A/L Past Paper Series'),
('alict_01315', 7, 'Database Management Systems', 'Consider the following SQL products SET price = price * 0.9 WHERE category_id IN ( SELECT category_id FROM categories WHERE category_name = does this SQL statement do?', '["Reduces the price of all products by 10%", "Reduces the price of electronic products by 10%", "Updates the price of all categories to 90%", "Deletes all electronic products", "Adds a new category"]'::jsonb, 2, 'UPDATE This statement is modifying records in the products table. UPDATE products( products SET price = price * 0.9: It reduces the price by 10% (i.e., 90% of original price). SET price = price * WHERE category_id IN (', NULL, NULL, 'medium', 'Database Management Systems', NULL, 1315, 'A/L Past Paper Series'),
